/**
 * Workbook layout (the legacy spreadsheet format) and canonical expectations
 * of the public demo workbook (fictional data, generated by
 * ./demo-workbook.ts). Anything that differs fails closed.
 */
import { IMPORT_IDENTITY } from "../import-identity/identity";
import type { CategoryField, LocationField, MovementField, ProductField } from "./model";

export const IMPORT_VERSION = "tralyn-demo-v1";
export const SOURCE_REFERENCE_PREFIX = "tralyn-demo";

/** Versioned, public-safe canonical workbook (relative to the repository root). */
export const CANONICAL_WORKBOOK_PATH = "fixtures/tralyn-demo.xlsx";

/** Profile the plan writes on behalf of (resolved to an id only at import time). */
export const EXECUTED_BY_EMAIL = IMPORT_IDENTITY.email;

// -----------------------------------------------------------------------------
// Sheet layout: exact headers, in order. `derived` columns are workbook
// formulas (lookups/totals) used only as cross-checks, never as source data.
// -----------------------------------------------------------------------------
export interface ColumnSpec<F extends string> {
  header: string;
  field: F;
  derived?: boolean;
}

export const SHEETS = {
  categories: "CATEGORIAS",
  locations: "LOCALIZAÇÕES",
  products: "PRODUTOS",
  movements: "MOVIMENTAÇÕES",
} as const;

