export const UNSUPPORTED_DATA_SHEETS = ["FORNECEDORES"] as const;

// -----------------------------------------------------------------------------
// Expectations (the canonical file; tests pass their own for synthetic files)
// -----------------------------------------------------------------------------
export interface SpecialProductExpectation {
  code: string;
  initialStock?: number;
  brand?: string | null;
  model?: string | null;
  /** True when the product must NOT receive an OPENING_BALANCE. */
  noOpening?: boolean;
  historical?: { legacyType: string; quantity: number; date: string; responsible: string }[];
}

export interface ImportExpectations {
  fileName: string;
  sha256: string;
  /** Only these locations are real; every other one must be listed in excludedLocations. */
  realLocations: string[];
  excludedLocations: { code: string; reason: string }[];
  counts: {
    categories: number;
    locations: number;
    suppliers: number;
    products: number;
    openingBalances: number;
    historicalMovements: number;
  };
  openingQuantity: number;
  historicalNet: number;
  finalQuantity: number;
  /** Initial stock per category name (before historical movements). */
  initialByCategory: Record<string, number>;
  specialProducts: SpecialProductExpectation[];
}

